const DOC_MAP = Object.fromEntries(DOCS.map(d=>[d.key,d]));

/* ============================================================
   REFERENCE NUMBER SYSTEM
   ============================================================ */
function prefixOf(doc,d){ return typeof doc.prefix==='function' ? doc.prefix(d||{}) : doc.prefix; }
function nextRefPreview(prefix){
  const key=prefix+'_'+yr();
  const n=(STATE.refCounters[key]||0)+1;
  return `ADSWISE/${prefix}/${yr()}/${String(n).padStart(3,'0')}`;
}
function commitRef(prefix){
  const key=prefix+'_'+yr();
  STATE.refCounters[key]=(STATE.refCounters[key]||0)+1;
  LS.save('refCounters',STATE.refCounters);
  return `ADSWISE/${prefix}/${yr()}/${String(STATE.refCounters[key]).padStart(3,'0')}`;
}

/* ============================================================
   NAVIGATION
   ============================================================ */
function buildNav(filter=''){
  const groups={};
  DOCS.forEach(d=>{ if(filter && !d.label.toLowerCase().includes(filter.toLowerCase())) return; (groups[d.group]=groups[d.group]||[]).push(d); });
  let html=`<div class="nav-item ${activeKey==='dashboard'?'active':''}" onclick="go('dashboard')"><span class="ic">▣</span> Dashboard</div>`;
  for(const g in groups){
    html+=`<div class="nav-group">${g}</div>`;
    groups[g].forEach(d=>{ html+=`<div class="nav-item ${activeKey===d.key?'active':''}" onclick="openDoc('${d.key}')"><span class="ic">${d.icon}</span> ${d.label}</div>`; });
  }
  html+=`<div class="nav-group">Data &amp; Setup</div>
    <div class="nav-item ${activeKey==='master'?'active':''}" onclick="go('master')"><span class="ic">▦</span> HR Master Data</div>
    <div class="nav-item ${activeKey==='settings'?'active':''}" onclick="go('settings')"><span class="ic">⚙</span> Letterhead &amp; Settings</div>`;
  document.getElementById('nav').innerHTML=html;
}
let activeKey='dashboard';
function setView(v){ document.querySelectorAll('.view').forEach(x=>x.classList.remove('active')); document.getElementById('view-'+v).classList.add('active'); document.getElementById('main').scrollTop=0; }
function toggleSidebar(force){ const s=document.getElementById('sidebar'),sc=document.getElementById('scrim'); const open=force===undefined?!s.classList.contains('open'):force; s.classList.toggle('open',open); sc.classList.toggle('show',open); }

function go(v){
  activeKey=v; toggleSidebar(false);
  if(v==='dashboard'){ renderDashboard(); setView('dashboard'); setTop('Overview','Dashboard'); }
  if(v==='settings'){ renderSettings(); setView('settings'); setTop('Letterhead & Settings','Setup'); }
  if(v==='master'){ renderMaster(); setView('master'); setTop('HR Master Data','Records'); }
  buildNav(document.getElementById('navSearch').value);
}
function setTop(title,crumb){ document.getElementById('pageTitle').textContent=title; document.getElementById('crumb').textContent=crumb.toUpperCase(); }

/* ============================================================
   DASHBOARD
   ============================================================ */
function renderDashboard(){
  const emp=STATE.employees;
  const active=emp.filter(e=>e.status==='Active').length;
  const docsGenerated=Object.values(STATE.refCounters).reduce((a,b)=>a+b,0);
  const drafts=Object.keys(STATE.drafts).length;
  const tiles=DOCS.map(d=>`<div class="doc-tile card" onclick="openDoc('${d.key}')">
      ${d.legal?'<span class="legal-dot">REVIEW</span>':''}
      <div class="ic">${d.icon}</div><div class="t">${d.label}</div>
      <div class="ref">${nextRefPreview(prefixOf(d,{}))}</div></div>`).join('');
  document.getElementById('view-dashboard').innerHTML=`
    <div class="dash-hero">
      <h1>HR Document <span>Studio</span></h1>
      <p>Generate branded, print-ready HR documents across the full employee lifecycle — from offer to exit. ${STATE.letterhead&&STATE.letterhead.img?'Using your custom letterhead.':'Official Adswise letterhead is active on every page.'}</p>
    </div>
    <div class="stat-grid">
      <div class="stat card glass"><div class="k">Employees on file</div><div class="v">${emp.length}</div><div class="d">${active} active</div></div>
      <div class="stat card glass"><div class="k">Documents issued</div><div class="v">${docsGenerated}</div><div class="d">across all types this year</div></div>
      <div class="stat card glass"><div class="k">Saved drafts</div><div class="v">${drafts}</div><div class="d">resume any time</div></div>
      <div class="stat card glass"><div class="k">Letterhead</div><div class="v" style="font-size:18px">${STATE.letterhead&&STATE.letterhead.img?'Custom':'Official'}</div><div class="d">on every page</div></div>
    </div>
    <div class="section-head"><h2>Create a document</h2><button class="btn ghost" onclick="go('master')">Open Master Data ▦</button></div>
    <div class="doc-grid">${tiles}</div>`;
}

/* ============================================================
   SETTINGS  (letterhead + signatory)
   ============================================================ */
function renderSettings(){
  const lh=STATE.letterhead, s=STATE.signatory;
  document.getElementById('view-settings').innerHTML=`
   <div class="editor">
    <div class="panel card">
      <h3>⚙ Company Letterhead</h3>
      <div class="panel-sub">The official Adswise Marketing letterhead (logo, watermark and contact block) is <b>built in</b> and applied to every document automatically. Upload a file below only if you want to override it — a tall A4 image is used as a full-page background; a wide image is used as a header strip.</div>
      <div class="upload-zone" id="lhZone" onclick="document.getElementById('lhInput').click()">
        <div class="uz-ic">⬆</div><div class="uz-t">Upload company letterhead</div><div class="uz-s">PNG / JPG · click to browse</div>
      </div>
      <input type="file" id="lhInput" accept="image/png,image/jpeg" hidden onchange="onLetterhead(event)">
      <div id="lhThumb">${lh?lhThumbHTML(lh):''}</div>

      <h3 style="margin-top:24px">✒ Authorised Signatory</h3>
      <div class="panel-sub">Used in the right-hand signature block of issued documents.</div>
      <div class="fgrid" style="margin-top:12px">
        <div class="field"><label>Signatory Name</label><input id="sigName" value="${esc(s.name)}" oninput="saveSignatory()"></div>
        <div class="field"><label>Designation</label><input id="sigDes" value="${esc(s.designation)}" oninput="saveSignatory()"></div>
      </div>
      <div class="upload-zone" style="margin-top:12px" onclick="document.getElementById('sigInput').click()">
        <div class="uz-ic">✒</div><div class="uz-t">Upload signature image</div><div class="uz-s">PNG with transparent background works best</div>
      </div>
      <input type="file" id="sigInput" accept="image/png,image/jpeg" hidden onchange="onSignature(event)">
      <div id="sigThumb">${s.img?`<div class="thumb"><img src="${s.img}"><span class="nm">Signature loaded</span><span class="rm" onclick="clearSig()">Remove</span></div>`:''}</div>
    </div>

    <div class="panel card">
      <h3>ℹ Data &amp; storage</h3>
      <div class="panel-sub" style="margin-bottom:14px">Everything you enter stays in this browser only (localStorage). Nothing is uploaded to any server. To keep your data, open this same HTML file from the same browser on the same device.</div>
      <div class="legal-banner"><span class="lb-ic">⚠</span><div class="lb-t"><b>Legal review required.</b> Documents marked <b>REVIEW</b> (agreements, NDA, warning, show-cause, PIP, full &amp; final) are starting drafts based on common Indian practice. State-specific Shops &amp; Establishments rules, PF/ESIC/gratuity thresholds and disciplinary procedure must be confirmed by a qualified advocate before issue.</div></div>
      <div style="margin-top:18px;display:flex;gap:10px;flex-wrap:wrap">
        <button class="btn ghost" onclick="exportBackup()">⬇ Export all data (JSON)</button>
        <button class="btn ghost" onclick="document.getElementById('importInput').click()">⬆ Import data</button>
        <input type="file" id="importInput" accept="application/json" hidden onchange="importBackup(event)">
        <button class="btn ghost" style="color:var(--err);border-color:rgba(192,57,43,.4)" onclick="resetAll()">🗑 Reset everything</button>
      </div>
    </div>
   </div>`;
}
function lhThumbHTML(lh){ return `<div class="thumb"><img src="${lh.img}" style="max-width:220px;height:auto"><span class="nm">Custom letterhead (${lh.mode==='full'?'full-page':'header strip'})</span><span class="rm" onclick="clearLetterhead()">Remove — use official</span></div>`; }
function onLetterhead(e){ const f=e.target.files[0]; if(!f)return; const r=new FileReader(); r.onload=()=>{
  const probe=new Image();
  probe.onload=()=>{
    const mode = probe.height/probe.width > 1.05 ? 'full' : 'strip';
    STATE.letterhead={img:r.result,mode};
    LS.save('letterhead',STATE.letterhead);
    document.getElementById('lhThumb').innerHTML=lhThumbHTML(STATE.letterhead);
    toast(mode==='full'?'Full-page letterhead saved — used as the page background.':'Header-strip letterhead saved — placed at the top of each document.','ok');
  };
  probe.src=r.result;
}; r.readAsDataURL(f); }
function clearLetterhead(){ STATE.letterhead=null; LS.save('letterhead',null); document.getElementById('lhThumb').innerHTML=''; toast('Reverted to the official Adswise letterhead.','ok'); }
function onSignature(e){ const f=e.target.files[0]; if(!f)return; const r=new FileReader(); r.onload=()=>{ STATE.signatory.img=r.result; LS.save('signatory',STATE.signatory); document.getElementById('sigThumb').innerHTML=`<div class="thumb"><img src="${r.result}"><span class="nm">Signature loaded</span><span class="rm" onclick="clearSig()">Remove</span></div>`; toast('Signature saved.','ok'); }; r.readAsDataURL(f); }
function clearSig(){ STATE.signatory.img=null; LS.save('signatory',STATE.signatory); document.getElementById('sigThumb').innerHTML=''; }
function saveSignatory(){ STATE.signatory.name=document.getElementById('sigName').value; STATE.signatory.designation=document.getElementById('sigDes').value; LS.save('signatory',STATE.signatory); }

/* ============================================================
   DOCUMENT EDITOR
   ============================================================ */
function openDoc(key){
  const doc=DOC_MAP[key]; if(!doc)return;
  activeKey=key; toggleSidebar(false); buildNav(document.getElementById('navSearch').value);
  STATE.current={key, data: Object.assign({}, STATE.drafts[key]||{})};
  setTop(doc.label,doc.group);
  renderEditor(doc);
  setView('editor');
}
function renderEditor(doc){
  const d=STATE.current.data;
  const formHTML=doc.fields.map(sec=>`
    <div class="fset"><div class="fset-title"><span>${sec.icon||'›'}</span>${sec.title}</div>
      <div class="fgrid">${sec.fields.map(f=>fieldHTML(f,d[f.id])).join('')}</div>
    </div>`).join('');
  document.getElementById('view-editor').innerHTML=`
   <div class="editor">
    <div class="panel card">
      <h3>${doc.icon} ${doc.label}</h3>
      <div class="panel-sub">Reference will be issued as <b id="refPrev">${nextRefPreview(prefixOf(doc,d))}</b> on generation.</div>
      <div class="progress-wrap"><div class="progress-bar"><div class="progress-fill" id="progFill"></div></div>
        <div class="progress-lbl"><span>Form completion</span><span id="progPct">0%</span></div></div>
      ${doc.legal?`<div class="legal-banner"><span class="lb-ic">⚠</span><div class="lb-t"><b>Legal review required before issue.</b> This is a drafting aid, not legal advice. Have a qualified advocate confirm clauses, notice periods and statutory compliance.</div></div>`:''}
      <form id="docForm" onsubmit="return false">${formHTML}</form>
      <div class="editor-actions">
        <button class="btn primary" onclick="generate()">✦ Generate &amp; assign reference</button>
        <button class="btn ghost" onclick="window.print()">🖨 Print / Save PDF</button>
        <button class="btn ghost" onclick="downloadPDF()">⬇ Quick PDF</button>
        <button class="btn gold" onclick="saveToMaster()">▦ Save to Master Data</button>
        <button class="btn ghost" onclick="saveDraft()">💾 Save draft</button>
        <button class="btn ghost" onclick="clearForm()">✕ Clear</button>
      </div>
    </div>
    <div class="preview-pane">
     <div class="card" style="overflow:hidden">
      <div class="preview-toolbar">
        <span class="pt-t">Live preview · A4 · letterhead repeats per page in Print/PDF</span>
        <button class="zoom-btn" onclick="zoomDoc(-1)">−</button><button class="zoom-btn" onclick="zoomDoc(1)">+</button>
      </div>
      <div class="preview-scroll"><div id="docMount"></div></div>
     </div>
    </div>
   </div>`;
  // wire inputs
  document.querySelectorAll('#docForm [data-fid]').forEach(el=>{
    el.addEventListener('input',()=>{ STATE.current.data[el.dataset.fid]=el.value; refreshPreview(doc); autoSave(); });
  });
  refreshPreview(doc);
}
function fieldHTML(f,val){
  val=val==null?'':val;
  const cls=f.full?'field full':'field';
  const req=f.req?'<span class="req"> *</span>':'';
  let input;
  if(f.type==='select'){ input=`<select data-fid="${f.id}">${f.options.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`; }
  else if(f.type==='textarea'){ input=`<textarea data-fid="${f.id}" placeholder="${esc(f.ph)}">${esc(val)}</textarea>`; }
  else { input=`<input type="${f.type}" data-fid="${f.id}" value="${esc(val)}" placeholder="${esc(f.ph)}">`; }
  return `<div class="${cls}"><label>${esc(f.label)}${req}</label>${input}${f.hint?`<span class="hint">${esc(f.hint)}</span>`:''}</div>`;
}
let zoom=0.82;
function zoomDoc(dir){ zoom=Math.min(1.1,Math.max(0.5,zoom+dir*0.08)); const a=document.querySelector('#docMount .a4'); if(a)a.style.transform=`scale(${zoom})`; }

function docPageHTML(doc,d,refNo){
  const lh=activeLH(), full=lh.mode==='full';
  const bgLayer = full ? `<div class="lh-screen" style="background-image:url('${lh.img}')"></div><img class="lh-bg" src="${lh.img}" alt="">` : '';
  const strip   = !full ? `<div class="a4-lh"><img src="${lh.img}"></div>` : '';
  const subj = typeof doc.subject==='function' ? doc.subject(d) : (doc.subject||doc.label);
  const head = doc.letterFormat
    ? `<div class="doc-ref-row"><span>Ref. No.: <b>${esc(refNo)}</b></span><span>Date: ${niceDate(todayISO())}</span></div>
       <div class="letter-meta">
         <p><b>PRIVATE &amp; CONFIDENTIAL</b></p>
         <p style="margin-top:10px">To,</p>
         <p><b>${esc(d.fullName||'[Full Name]')}</b>${(d.candAddr||d.addrCur)?'<br>'+esc(d.candAddr||d.addrCur).replace(/\n/g,'<br>'):''}</p>
         <p class="letter-subject">Subject: ${esc(subj)}</p>
       </div>`
    : `<div class="doc-ref-row"><span>Ref: <b>${esc(refNo)}</b></span><span>Date: ${niceDate(todayISO())}</span></div>
       <div class="doc-title">${esc(doc.label)}</div><div class="doc-title-rule"></div>`;
  const footer = full ? '' : `<div class="a4-foot"><span>Adswise Marketing · Your Growth Is Our Business</span><span>www.adswisemarketing.com</span></div>`;
  const inner = `${head}<div class="doc-body">${doc.body(d)}</div>`;
  const flow = full
    ? `<table class="flow"><thead><tr><td><div class="ps-top"></div></td></tr></thead>
       <tfoot><tr><td><div class="ps-bot"></div></td></tr></tfoot>
       <tbody><tr><td class="flow-td">${inner}</td></tr></tbody></table>`
    : inner;
  return `<div class="a4 ${full?'lh-full':''}" id="a4page" style="transform:scale(${zoom})">
    ${bgLayer}${strip}
    <div class="a4-body">
      ${flow}
    </div>
    ${doc.legal?'<div class="draft-stamp" style="z-index:2">DRAFT</div>':''}
    ${footer}
  </div>`;
}
function refreshPreview(doc){
  const d=STATE.current.data;
  const refNo=STATE.current.assignedRef||nextRefPreview(prefixOf(doc,d));
  const rp=document.getElementById('refPrev'); if(rp&&!STATE.current.assignedRef)rp.textContent=refNo;
  document.getElementById('docMount').innerHTML=docPageHTML(doc,d,refNo);
  // completion %
  const req=doc.fields.flatMap(s=>s.fields).filter(f=>f.req);
  const filled=req.filter(f=>String(d[f.id]||'').trim()!=='').length;
  const pct = req.length? Math.round(filled/req.length*100) : 100;
  const pf=document.getElementById('progFill'),pp=document.getElementById('progPct');
  if(pf){pf.style.width=pct+'%';pp.textContent=pct+'%';}
}
function validate(doc){
  const d=STATE.current.data; let ok=true; let firstBad=null;
  doc.fields.flatMap(s=>s.fields).filter(f=>f.req).forEach(f=>{
    const el=document.querySelector(`[data-fid="${f.id}"]`);
    const bad=String(d[f.id]||'').trim()==='';
    if(el)el.classList.toggle('invalid',bad);
    if(bad){ok=false;firstBad=firstBad||el;}
  });
  if(!ok){ toast('Please complete the required fields (marked *).','err'); if(firstBad)firstBad.focus(); }
  return ok;
}
function generate(){
  const doc=DOC_MAP[STATE.current.key];
  if(!validate(doc))return;
  STATE.current.assignedRef=commitRef(prefixOf(doc,STATE.current.data));
  document.getElementById('refPrev').textContent=STATE.current.assignedRef;
  refreshPreview(doc);
  toast('Reference '+STATE.current.assignedRef+' assigned. Ready to print or save.','ok');
}
let saveTimer=null;
function autoSave(){ clearTimeout(saveTimer); saveTimer=setTimeout(()=>{ STATE.drafts[STATE.current.key]=STATE.current.data; LS.save('drafts',STATE.drafts); },800); }
function saveDraft(){ STATE.drafts[STATE.current.key]=STATE.current.data; LS.save('drafts',STATE.drafts); toast('Draft saved.','ok'); }
function clearForm(){ STATE.current.data={}; delete STATE.drafts[STATE.current.key]; LS.save('drafts',STATE.drafts); renderEditor(DOC_MAP[STATE.current.key]); toast('Form cleared.','warn'); }

function saveToMaster(){
  const d=STATE.current.data;
  if(!d.fullName){ toast('Add the employee name before saving to Master Data.','err'); return; }
  const r=salaryRollup(d);
  const rec={
    empId:d.empId||('ADW-'+Date.now().toString().slice(-5)),
    name:d.fullName, department:d.department||'—', designation:d.designation||'—',
    doj:d.doj||'', ctc:r.annualCTC||0,
    status:(STATE.current.key==='relieving'||STATE.current.key==='fnf'||STATE.current.key==='experience')?'Exited':(d.confirmDate?'Active':'Probation'),
    email:d.emailO||d.emailP||'', mobile:d.mobile||''
  };
  const i=STATE.employees.findIndex(e=>e.empId===rec.empId);
  if(i>=0) STATE.employees[i]=Object.assign(STATE.employees[i],rec); else STATE.employees.push(rec);
  LS.save('employees',STATE.employees);
  toast('Saved to HR Master Data.','ok');
}
function downloadPDF(){
  const node=document.getElementById('a4page'); if(!node){toast('Nothing to export.','err');return;}
  const clone=node.cloneNode(true); clone.style.transform='none'; clone.style.boxShadow='none';
  const wrap=document.createElement('div'); wrap.appendChild(clone);
  toast('Building PDF… for multi-page letterhead, prefer Print → Save as PDF.','warn');
  html2pdf().set({margin:0,filename:(STATE.current.assignedRef||DOC_MAP[STATE.current.key].label).replace(/[\/ ]/g,'-')+'.pdf',
    image:{type:'jpeg',quality:0.98}, html2canvas:{scale:2,useCORS:true}, jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},
    pagebreak:{mode:['css','legacy']}}).from(wrap).save();
}

/* ============================================================
   HR MASTER DATA SHEET
   ============================================================ */
let sortKey='name',sortDir=1;
function renderMaster(){
  document.getElementById('view-master').innerHTML=`
    <div class="panel card" style="padding:20px 22px">
     <h3>▦ HR Master Data Sheet</h3>
     <div class="panel-sub">Employees saved from any document. Click a column to sort.</div>
     <div class="table-tools" style="margin-top:16px">
       <input id="dtSearch" placeholder="Search name, ID, dept…" oninput="renderTable()" style="min-width:220px">
       <select id="dtStatus" onchange="renderTable()"><option value="">All statuses</option><option>Active</option><option>Probation</option><option>Exited</option></select>
       <select id="dtDept" onchange="renderTable()"><option value="">All departments</option></select>
       <span style="flex:1"></span>
       <button class="btn ghost" onclick="exportCSV()">⬇ Export CSV</button>
       <button class="btn ghost" onclick="exportXLS()">⬇ Export Excel</button>
     </div>
     <div class="dt-wrap"><div id="dtBody"></div></div>
    </div>`;
  const depts=[...new Set(STATE.employees.map(e=>e.department).filter(Boolean))];
  document.getElementById('dtDept').innerHTML='<option value="">All departments</option>'+depts.map(d=>`<option>${esc(d)}</option>`).join('');
  renderTable();
}
function currentRows(){
  const q=(document.getElementById('dtSearch')?.value||'').toLowerCase();
  const st=document.getElementById('dtStatus')?.value||'';
  const dp=document.getElementById('dtDept')?.value||'';
  return STATE.employees.filter(e=>{
    const hit=[e.name,e.empId,e.department,e.designation].join(' ').toLowerCase().includes(q);
    return hit && (!st||e.status===st) && (!dp||e.department===dp);
  }).sort((a,b)=>{ let x=a[sortKey],y=b[sortKey]; if(sortKey==='ctc'){x=+x;y=+y;} if(x<y)return -1*sortDir; if(x>y)return 1*sortDir; return 0;});
}
function renderTable(){
  const rows=currentRows();
  const cols=[['empId','Employee ID'],['name','Name'],['department','Department'],['designation','Designation'],['doj','Joining'],['ctc','Annual CTC'],['status','Status']];
  if(!STATE.employees.length){ document.getElementById('dtBody').innerHTML=`<div class="empty-state"><div class="es-ic">▦</div><p style="margin-top:10px">No employees yet. Open any document, fill it in, and click <b>Save to Master Data</b>.</p></div>`; return; }
  const pill=s=>`<span class="pill ${s==='Active'?'active':s==='Exited'?'exited':'probation'}">${esc(s)}</span>`;
  document.getElementById('dtBody').innerHTML=`<table class="dt"><thead><tr>${cols.map(c=>`<th onclick="setSort('${c[0]}')">${c[1]} ${sortKey===c[0]?(sortDir>0?'▲':'▼'):''}</th>`).join('')}</tr></thead>
    <tbody>${rows.map(e=>`<tr><td>${esc(e.empId)}</td><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(e.designation)}</td><td>${niceDate(e.doj)}</td><td>${fmtINR(e.ctc)}</td><td>${pill(e.status)}</td></tr>`).join('')}</tbody></table>`;
}
function setSort(k){ if(sortKey===k)sortDir*=-1; else{sortKey=k;sortDir=1;} renderTable(); }
function exportCSV(){
  const rows=currentRows(); if(!rows.length){toast('Nothing to export.','warn');return;}
  const head=['Employee ID','Name','Department','Designation','Date of Joining','Annual CTC','Status','Email','Mobile'];
  const csv=[head.join(',')].concat(rows.map(e=>[e.empId,e.name,e.department,e.designation,e.doj,e.ctc,e.status,e.email,e.mobile].map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(','))).join('\n');
  dl(new Blob([csv],{type:'text/csv'}),'adswise-hr-master.csv'); toast('CSV exported.','ok');
}
function exportXLS(){
  const rows=currentRows(); if(!rows.length){toast('Nothing to export.','warn');return;}
  const head=['Employee ID','Name','Department','Designation','Date of Joining','Annual CTC','Status'];
  const html=`<table><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr>${rows.map(e=>`<tr><td>${esc(e.empId)}</td><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(e.designation)}</td><td>${esc(e.doj)}</td><td>${e.ctc}</td><td>${esc(e.status)}</td></tr>`).join('')}</table>`;
  dl(new Blob([`<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body>${html}</body></html>`],{type:'application/vnd.ms-excel'}),'adswise-hr-master.xls'); toast('Excel file exported.','ok');
}
function dl(blob,name){ const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000); }

/* ============================================================
   BACKUP / RESET / THEME / TOAST
   ============================================================ */
function exportBackup(){ dl(new Blob([JSON.stringify({letterhead:STATE.letterhead,signatory:STATE.signatory,refCounters:STATE.refCounters,drafts:STATE.drafts,employees:STATE.employees},null,2)],{type:'application/json'}),'adswise-hrms-backup.json'); toast('Backup exported.','ok'); }
function importBackup(e){ const f=e.target.files[0]; if(!f)return; const r=new FileReader(); r.onload=()=>{ try{ const j=JSON.parse(r.result); ['letterhead','signatory','refCounters','drafts','employees'].forEach(k=>{ if(j[k]!==undefined){STATE[k]=j[k];LS.save(k,j[k]);} }); toast('Data imported.','ok'); go('dashboard'); }catch(err){ toast('Invalid backup file.','err'); } }; r.readAsText(f); }
function resetAll(){ if(!confirm('This permanently clears all letterhead, drafts and employee records in this browser. Continue?'))return; ['letterhead','signatory','refCounters','drafts','employees'].forEach(k=>localStorage.removeItem('adw_'+k)); location.reload(); }
function toggleTheme(){ const h=document.documentElement; const t=h.getAttribute('data-theme')==='dark'?'light':'dark'; h.setAttribute('data-theme',t); LS.save('theme',t); }
function toast(msg,type='info'){ const t=document.createElement('div'); t.className='toast '+type; t.innerHTML=`<span>${type==='ok'?'✓':type==='err'?'✕':type==='warn'?'⚠':'ℹ'}</span><span>${esc(msg)}</span>`; document.getElementById('toasts').appendChild(t); setTimeout(()=>{t.style.opacity='0';t.style.transition='.3s';setTimeout(()=>t.remove(),300);},3400); }

/* keyboard: Ctrl+S save draft, Ctrl+P handled by browser */
document.addEventListener('keydown',e=>{ if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){ if(STATE.current&&document.getElementById('view-editor').classList.contains('active')){ e.preventDefault(); saveDraft(); } } });
document.getElementById('navSearch').addEventListener('input',e=>buildNav(e.target.value));

/* ---------- init ---------- */
(function init(){
  const t=LS.load('theme',null); if(t)document.documentElement.setAttribute('data-theme',t);
  buildNav(); renderDashboard(); setTop('Overview','Dashboard');
})();

/* ---------- print: inject letterhead as repeating header ---------- */
const printStyle=document.createElement('style');
document.head.appendChild(printStyle);
function buildPrintCSS(){
  const full = activeLH().mode==='full';
  if(full){
    // Full-page letterhead printing:
    //  - @page margin 0 so the fixed letterhead image covers the physical page on EVERY page
    //  - thead/tfoot spacers repeat per page, keeping text clear of the header artwork & contact block
    return `@media print{
      body *{visibility:hidden!important}
      #docMount,#docMount *{visibility:visible!important}
      #docMount{position:absolute;left:0;top:0;width:100%}
      #docMount .a4{transform:none!important;box-shadow:none!important;width:100%!important;min-height:auto!important;background:transparent!important}
      #docMount .lh-screen{display:none!important}
      #docMount .lh-bg{display:block!important;position:fixed!important;top:0;left:0;width:100vw;height:100vh;object-fit:fill;z-index:0}
      #docMount .a4.lh-full .a4-body{padding:0!important;position:relative;z-index:1}
      #docMount .ps-top{height:58mm!important}
      #docMount .ps-bot{height:34mm!important}
      #docMount .flow-td{padding:0 16mm!important}
      .draft-stamp{position:fixed!important;z-index:2}
      @page{size:A4;margin:0}
    }`;
  }
  return `@media print{
    body *{visibility:hidden!important}
    #docMount,#docMount *{visibility:visible!important}
    #docMount{position:absolute;left:0;top:0;width:100%}
    #docMount .a4{transform:none!important;box-shadow:none!important;width:100%!important;min-height:auto!important}
    .a4-foot{position:fixed;bottom:0}
    @page{size:A4;margin:14mm 0}
  }`;
}
window.addEventListener('beforeprint',()=>{ printStyle.textContent=buildPrintCSS(); });
